package com.ensam.inventia.security;
import com.ensam.inventia.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor public class UserDetailsServiceImpl implements UserDetailsService { private final UserRepository users; public UserDetails loadUserByUsername(String email){ var u=users.findByEmail(email).orElseThrow(()->new UsernameNotFoundException(email)); return User.withUsername(u.getEmail()).password(u.getPassword()).disabled(!u.getEnabled()).authorities(u.getRole().getName().name()).build(); } }
